-- composition of rule kernels column_lifetime x join_order (duckdb), template exists
SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS ka WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 0 AS c0 UNION SELECT 7 AS c0) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT 0 AS c0 UNION SELECT 7 AS c0) AS kb) > 0 THEN (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 100.0::float8 AS c1, '-3 hours'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, (-1.5)::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 1000::bigint, 'A'::text) AS c2 FROM (SELECT FALSE AS c0) AS a1) AS ka) ELSE 0 END
